insert into public.programas (slug, nombre, tipo, etiqueta, url, resumen, descripcion, imagen, datos, video_youtube, video_miniatura, beneficios, libros, para_quien, disponibilidad, whatsapp_mensaje, formulario, en_home, activo, orden) values
  ('anual-elite', 'Anual Élite', 'individual', 'Programa integral', '/programas/integrales-individuales/programa-anual-elite/', 'Ayuda a tu hijo a consolidar sus bases matemáticas con un acompañamiento personalizado durante todo el año.', 'Ayuda a tu hijo a consolidar sus bases matemáticas con un acompañamiento personalizado durante todo el año.', '/img/programas/elite.webp', '[{"icono":"clases","texto":"Dos o más clases por semana"},{"icono":"reloj","texto":"50 minutos por cada clase"},{"icono":"virtual","texto":"Clases 100% virtuales"},{"icono":"seguimiento","texto":"Seguimiento completo"}]'::jsonb, 'IduzZnSBPvs', '/img/videos/elite.webp', '["Evaluación de entrada para identificar oportunidades.","Desarrollo de plan de trabajo a la medida del alumno.","Acompañamiento durante todo su proceso de estudios.","Informes en línea sobre el avance del programa.","Reunión virtual con su profesor de colegio.","Reuniones con nuestros tutores especializados de Matlab."]'::jsonb, '[]'::jsonb, 'primaria y secundaria', 'tarde y noche', 'Hola vengo de la página web, quiero más información del Programa Anual Élite 😎.', 'individual', true, true, 2),
  ('mensual-power', 'Mensual Power', 'individual', 'Programa integral', '/programas/integrales-individuales/programa-mensual-power/', 'Dale a tu hijo el acompañamiento necesario para absolver sus dudas y que se convierta en un crack en matemáticas.', 'Dale a tu hijo el acompañamiento necesario para absolver sus dudas y que se convierta en un crack en matemáticas.', '/img/programas/power.webp', '[{"icono":"clases","texto":"Una o más clases por semana"},{"icono":"reloj","texto":"50 minutos por cada clase"},{"icono":"virtual","texto":"Clases 100% virtuales"},{"icono":"check","texto":"Eliges la cantidad de clases"}]'::jsonb, '_LgBJIqqOJc', '/img/videos/power.webp', '["Evaluación de entrada para identificar oportunidades.","Desarrollo de plan de trabajo a la medida del alumno.","Acompañamiento durante todo su proceso de estudios.","Informes en línea sobre el avance del programa.","Reunión virtual con su profesor de colegio.","Reuniones con nuestros tutores especializados de Matlab."]'::jsonb, '[]'::jsonb, 'primaria y secundaria', 'tarde y noche', 'Hola vengo de la página web, quiero más información del Programa Mensual Power 💪.', 'individual', true, true, 1),
  ('mateinnovando', 'Mateinnovando', 'grupal', 'Taller grupal', '/programas/talleres-grupales/mateinnovando/', 'Potencia el talento matemático y financiero de tu hijo con la alianza estratégica que tenemos con todos los Innova Schools.', 'Desarrollado a partir de una alianza estratégica con Innova Schools, que integra la metodología de MatLab con los temas, contenidos y necesidades de aprendizaje de sus estudiantes.', '/img/programas/mateinnovando.webp', '[{"icono":"clases","texto":"2 clases por semana"},{"icono":"reloj","texto":"50 minutos por cada clase"},{"icono":"virtual","texto":"Clases 100% virtuales"},{"icono":"grupo","texto":"Grupos pequeños"}]'::jsonb, 'WaxA54UBkpQ', '/img/videos/mateinnovando.webp', '["Grupos pequeños.","Explicación didáctica.","Temas acorde al grado.","Participación activa."]'::jsonb, '[]'::jsonb, 'alumnos de Innova Schools', 'tarde y noche', 'Hola vengo de la página web, quiero más información del Programa Mateinnovando👌.', 'grupal', true, true, 3),
  ('taller-financiero', 'Taller Financiero', 'grupal', 'Taller grupal', '/programas/talleres-grupales/finanzas-para-jovenes/', 'Asegura el futuro financiero de tus hijos potenciando su educación financiera desde hoy.', 'Asegura el éxito financiero de tus hijos potenciando sus conocimientos de educación financiera.', '/img/programas/financiero.webp', '[{"icono":"clases","texto":"Una o dos clases por semana"},{"icono":"reloj","texto":"50 minutos por cada clase"},{"icono":"virtual","texto":"Clases 100% virtuales"},{"icono":"grupo","texto":"Grupos pequeños"}]'::jsonb, 'x-whJ-qQg38', '/img/videos/financiero.webp', '["Grupos pequeños.","Explicación didáctica.","Temas acorde al grado.","Participación activa."]'::jsonb, '[{"titulo":"Tu éxito financiero con Manzanitas","imagen":"/img/libros/manzanitas.webp"},{"titulo":"Los Tec X. Una visión financiera","imagen":"/img/libros/los-tec-x.webp"}]'::jsonb, '2do de primaria a 5to de secundaria', 'tarde y noche', 'Hola vengo de la página web, quiero más información del Taller Financiero 💰.', 'grupal', true, true, 4),
  ('clase-sos', 'Clase S.O.S.', 'sos', 'Clases de emergencia', '/clases-de-emergencia/', '¿Examen mañana? Clases individuales de emergencia para salvar el examen.', '', '/img/programas/sos.webp', '[]'::jsonb, 'Le_YwBzSggw', '/img/videos/sos.webp', '[]'::jsonb, '[]'::jsonb, null, null, 'Hola vengo de la página web, quiero más información de su Clase de Emergencia S.O.S 🚨.', 'sos', false, true, 5)
